update pages set contenu = '{"gabarit":"fiche","chapeau":"DANONE, à travers sa filiale Blédina, a confié à Migen le renfort continu de sa maintenance sur le site de Steenvoorde. Deux techniciens y sont intégrés en 3x8.","fiche":[],"contexte":"**Sur une ligne de nutrition infantile, la cadence perdue ne se rattrape pas.** Une équipe en production continue absorbe le correctif, les postes de nuit et les aléas avec le même effectif.\nLe site de Steenvoorde produit sur des lignes à haute cadence, où la fiabilité des équipements conditionne directement le volume sorti. Les enjeux posés étaient précis :\n**Disponibilité des lignes** : Tenir le taux de marche sur les liquides et sur le conditionnement poudre.\n**Réaction sur panne** : Raccourcir le temps entre l''arrêt et la remise en service.\n**Qualité et sécurité alimentaire** : Maintenir le niveau d''exigence imposé par la nutrition infantile.\n**Appui aux équipes internes** : Soutenir les équipes en place dans un rythme de production continue.","intervention":"**Renfort intégré, pas de structure en plus** : Deux techniciens de maintenance travaillent au sein des équipes Blédina. La continuité est assurée sans alourdir l''organisation du site.\n**Présence postée continue** : Les techniciens suivent le rythme 3x8. La maintenance est là quand la ligne tourne, pas seulement aux heures ouvrées.\n**Coordination avec les équipes du site** : Les interventions se décident avec les équipes internes, sur leurs priorités de production.\n**Des profils autonomes** : Polyvalence et autonomie sont les deux critères qui permettent de laisser un technicien en poste de nuit.\n**Un interlocuteur unique** : La mission est pilotée par les équipes Migen. Le client garde un contact, pas une liste qui change.\nLe périmètre technique sur site tient en quatre points :\nDiagnostic rapide des pannes sur lignes de production.\nDépannage en environnement automatisé, automates Schneider compris.\nMaintenance préventive et curative des équipements.\nSupport technique aux équipes de production.","resultats":[]}'::jsonb where path = '/preuves/danone-lignes-de-production/';
update pages set contenu = jsonb_set(contenu, '{fiche}', (contenu->'fiche') || '[{"libelle":"Client","valeur":"DANONE, filiale Blédina"},{"libelle":"Site","valeur":"Steenvoorde"},{"libelle":"Secteur","valeur":"Production agroalimentaire infantile"},{"libelle":"Périmètre","valeur":"Lignes liquides et conditionnement poudre"},{"libelle":"Effectif Migen","valeur":"2 techniciens de maintenance"},{"libelle":"Organisation","valeur":"Horaires postés 3x8, présence continue"},{"libelle":"Nature des travaux","valeur":"Maintenance préventive et curative, dépannage"},{"libelle":"Environnement technique","valeur":"Lignes automatisées, automates Schneider"}]'::jsonb) where path = '/preuves/danone-lignes-de-production/';
update pages set contenu = jsonb_set(contenu, '{resultats}', (contenu->'resultats') || '[{"valeur":"Des techniciens qualifiés et autonomes","libelle":"Opérationnels sans encadrement permanent."},{"valeur":"Une flexibilité d''organisation","libelle":"Le dispositif suit le rythme réel de la production."},{"valeur":"Une compétence alignée","libelle":"Le niveau technique correspond aux équipements en service."}]'::jsonb) where path = '/preuves/danone-lignes-de-production/';
